@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

<span class="badge bg-primary mb-3">@notifications.Count notification(s)</span>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override void OnInitialized()
    {
        // Restore from persisted state if available (avoids re-fetch after prerender)
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = NotificationService.GetNotifications();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the component is interactive (not during prerender)
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken).ConfigureAwait(false);

            var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
            var newItems = NotificationService.GetNotificationsSince(lastId);

            if (newItems.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications.AddRange(newItems);
                    PersistedNotifications = notifications;
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

